/**
 * geometry.test.js — The JS board geometry must match the backend's exactly.
 *
 * Both sides are compared against shared/board_geometry.json (generated by
 * backend/scripts/export_geometry.py). If intersection ids drifted, every API
 * call would refer to the wrong spots.
 */

import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { INTERSECTIONS } from './intersectionMap';
import { HEX_SIZE, SVG_CX, SVG_CY } from './hexGeometry';
import { DEFAULT_PORT_TYPES, PORT_SLOTS } from './ports';

const fixture = JSON.parse(
  readFileSync(new URL('../../../shared/board_geometry.json', import.meta.url), 'utf8'),
);

describe('board geometry parity with the backend', () => {
  it('has the same 54 intersections', () => {
    expect(INTERSECTIONS).toHaveLength(fixture.intersections.length);
  });

  it('numbers intersections identically (position, hexes, neighbours)', () => {
    for (const expected of fixture.intersections) {
      const node = INTERSECTIONS[expected.id];
      // Frontend works in SVG pixels; convert back to unit-hex coordinates
      expect((node.x - SVG_CX) / HEX_SIZE).toBeCloseTo(expected.x, 4);
      expect((node.y - SVG_CY) / HEX_SIZE).toBeCloseTo(expected.y, 4);
      expect([...node.hexIds].sort((a, b) => a - b)).toEqual(expected.hex_ids);
      expect(node.adjacentIds).toEqual(expected.adjacent_ids);
    }
  });

  it('uses the same port slots and default port types', () => {
    expect(PORT_SLOTS).toEqual(fixture.port_slots);
    expect(DEFAULT_PORT_TYPES).toEqual(fixture.default_port_types);
  });
});
